params.code:
// ==========================================
// SALES LEAD SCORING + DATA NORMALIZATION
// ==========================================

// Helper function to safely clean text
function cleanText(value) {
  if (value === undefined || value === null) {
    return '';
  }

  return String(value).trim();
}

// Helper function for lowercase comparison
function normalizeText(value) {
  return cleanText(value).toLowerCase();
}


// ==========================================
// 1. READ INPUT DATA
// ==========================================

const name = cleanText(inputData.name);
const company = cleanText(inputData.company);
const email = cleanText(inputData.email).toLowerCase();
const phone = cleanText(inputData.phone);

const source = cleanText(inputData.source);
const urgency = cleanText(inputData.urgency);
const requirement = cleanText(inputData.requirement);
const rawId = cleanText(inputData.raw_id);


// ==========================================
// 2. CLEAN BUDGET
// ==========================================

// Removes:
// $
// commas
// spaces
// currency text
// other non-numeric characters

const rawBudget = String(inputData.budget || '')
  .replace(/[^0-9.]/g, '');

const budget = parseFloat(rawBudget) || 0;


// ==========================================
// 3. LEAD SCORING
// ==========================================

let score = 0;


// ------------------------------------------
// URGENCY SCORE
// High = +30
// Medium = +20
// Low = +10
// ------------------------------------------

const urgencyNormalized = normalizeText(urgency);

if (urgencyNormalized.includes('high')) {
  score += 30;
} else if (urgencyNormalized.includes('medium')) {
  score += 20;
} else if (urgencyNormalized.includes('low')) {
  score += 10;
}


// ------------------------------------------
// BUDGET SCORE
// Above $5,000 = +30
// $1,000-$5,000 = +20
// Below $1,000 = +10
// ------------------------------------------

if (budget > 5000) {
  score += 30;

} else if (budget >= 1000 && budget <= 5000) {
  score += 20;

} else if (budget > 0 && budget < 1000) {
  score += 10;
}


// ------------------------------------------
// LEAD SOURCE SCORE
// Referral = +20
// LinkedIn = +15
// ------------------------------------------

const sourceNormalized = normalizeText(source);

if (sourceNormalized.includes('referral')) {
  score += 20;

} else if (sourceNormalized.includes('linkedin')) {
  score += 15;
}


// ==========================================
// 4. DETERMINE PRIORITY
// ==========================================

// 70+ = Hot
// 40-69 = Warm
// Below 40 = Cold

let priority = 'Cold';

if (score >= 70) {
  priority = 'Hot';

} else if (score >= 40) {
  priority = 'Warm';
}


// ==========================================
// 5. GENERATE LEAD ID
// ==========================================

// Example:
// LEAD-2026-4591

const year = new Date().getFullYear();

const randomNumber =
  Math.floor(1000 + Math.random() * 9000);

const leadId =
  `LEAD-${year}-${randomNumber}`;


// ==========================================
// 6. OUTPUT CLEAN DATA
// ==========================================

output = {

  lead_id: leadId,

  name: name,

  company: company,

  email: email,

  phone: phone,

  budget: budget,

  source: source,

  urgency: urgency,

  requirement_details: requirement,

  score: score,

  priority: priority,

  status: 'New',

  raw_record_id: rawId

};

